python3 -c "
import sqlite3,json,collections
c=sqlite3.connect('file:data/app.db?mode=ro',uri=True)
MAP={'Likes':'like','Defect':'defect','Difficult to Use':'difficult_to_use','Wants':'want'}
labels={};ch={}
for i,m in c.execute(\"select id,meta_json from source_item where kind='feedback'\"):
    m=json.loads(m); labels[i]={l['feedback_type'] for l in m['bmw_labels'] if l['feedback_type']}; ch[i]=m['channel']
sig=collections.defaultdict(set); cat=collections.defaultdict(set)
for i,t,k in c.execute(\"select source_item_id,feedback_type,category from signal where extractor_version='extract-v3'\"):
    sig[i].add(t)
lab=collections.Counter(l for s in labels.values() for l in s)
print('BMW label verbatim counts',lab, 'unlabelled',sum(1 for s in labels.values() if not s))
tot=collections.Counter();hit=collections.Counter();conf=collections.defaultdict(collections.Counter)
for i,ls in labels.items():
    for l in ls:
        tot[l]+=1; hit[l]+=MAP[l] in sig[i]; conf[l].update(sig[i] or {'<none>'})
for l in tot: print(l, tot[l], round(hit[l]/tot[l],3), conf[l].most_common(5))
# precision-ish: our defect signals on verbatims BMW labelled only Likes
n=sum(1 for i,ls in labels.items() if ls=={'Likes'} and sig[i]-{'like'})
print('BMW Likes-only verbatims with a non-like signal',n, 'of', sum(1 for ls in labels.values() if ls=={'Likes'}))
"

